unsafe extern "C" fn rt_jit_direct_enter_noarg_sub(
    run: *mut JitRun,
    state: *mut RawExecState,
    proc: i32,
) -> i32 {
    status_guard(|| {
        if run.is_null() || state.is_null() || proc < 0 {
            return ST_FAULT;
        }
        // SAFETY: null was rejected and compiled code gives unique run ownership.
        let run = unsafe { &mut *run };
        if run.program.is_null() {
            return ST_FAULT;
        }
        // SAFETY: `program` is installed from the owning CompiledImage for this run.
        let program = unsafe { &*run.program };
        let proc = proc as usize;
        if proc >= run.function_count {
            return ST_FAULT;
        }
        let Some(func) = program.funcs.get(proc) else {
            return ST_FAULT;
        };
        if func.param_count != 0 || func.return_local.is_some() {
            return ST_FAULT;
        }
        if run.frames.len() >= MAX_JIT_FRAMES {
            return rt_raise_out_of_stack(state);
        }

        let Ok(mut frame) = new_jit_frame(program, func) else {
            return ST_FAULT;
        };
        let enter_status = rt_err_enter_activation(state, &mut frame.saved_err);
        if enter_status != ST_OK {
            return enter_status;
        }
        run.frames.push(frame);
        ST_OK
    })
}

unsafe extern "C" fn rt_jit_direct_exit_noarg_sub(
    run: *mut JitRun,
    state: *mut RawExecState,
    status: i32,
) -> i32 {
    status_guard(|| {
        if run.is_null() || state.is_null() {
            return ST_FAULT;
        }
        // SAFETY: null was rejected and compiled code gives unique run ownership.
        let run = unsafe { &mut *run };
        let Some(frame) = run.frames.pop() else {
            return ST_FAULT;
        };
        prune_for_each_from_depth(run, run.frames.len());
        prune_param_array_aliases_from_depth(run, run.frames.len());
        let restore_status = rt_err_restore_activation(state, &frame.saved_err);
        if restore_status != ST_OK {
            restore_status
        } else {
            status
        }
    })
}

