fn checked_i32_to_slot_with_store(
    state: *mut RawExecState,
    run: *mut JitRun,
    lhs: i32,
    rhs: i32,
    area: u32,
    index: u32,
    shim: extern "C" fn(*mut RawExecState, i32, i32, *mut i32) -> i32,
    store: unsafe extern "C" fn(*mut JitRun, u32, u32, i32) -> i32,
) -> i32 {
    status_guard(|| {
        let mut out = 0;
        let status = shim(state, lhs, rhs, &mut out);
        if status != ST_OK {
            return status;
        }
        // SAFETY: forwarding the same run pointer received from compiled code.
        unsafe { store(run, area, index, out) }
    })
}

