    fn branch_program() -> OxProgram {
        let n = LocalId(0);
        let b = LocalId(1);
        let cond = TempId(0);
        let entry = OxBlock {
            id: BlockId(0),
            instrs: vec![
                OxInst::Compare {
                    dst: OxPlace::Temp(cond),
                    op: CmpOp::Lt,
                    lhs: OxOperand::Const(OxConst::I32(1)),
                    rhs: OxOperand::Const(OxConst::I32(2)),
                    mode: StringCompareMode::Binary,
                },
                OxInst::Assign {
                    dst: OxPlace::Local(b),
                    value: OxOperand::Use(OxPlace::Temp(cond)),
                },
            ],
            fault_target: Some(BlockId(3)),
            terminator: OxTerminator::Branch {
                cond: OxOperand::Use(OxPlace::Local(b)),
                then_blk: BlockId(1),
                else_blk: BlockId(2),
            },
        };
        let then_blk = OxBlock {
            id: BlockId(1),
            instrs: vec![OxInst::Assign {
                dst: OxPlace::Local(n),
                value: OxOperand::Const(OxConst::I32(42)),
            }],
            fault_target: Some(BlockId(3)),
            terminator: OxTerminator::Return,
        };
        let else_blk = OxBlock {
            id: BlockId(2),
            instrs: vec![OxInst::Assign {
                dst: OxPlace::Local(n),
                value: OxOperand::Const(OxConst::I32(13)),
            }],
            fault_target: Some(BlockId(3)),
            terminator: OxTerminator::Return,
        };
        let fault = OxBlock {
            id: BlockId(3),
            instrs: Vec::new(),
            fault_target: None,
            terminator: OxTerminator::FaultDispatch {
                resume: BlockId(0),
                resume_next: BlockId(4),
            },
        };
        let exit = OxBlock {
            id: BlockId(4),
            instrs: Vec::new(),
            fault_target: None,
            terminator: OxTerminator::Return,
        };
        let main = OxFunc {
            name: "Main".to_string(),
            kind: ProcedureKind::Sub,
            locals: vec![
                OxLocal {
                    name: "n".to_string(),
                    ty: OxTy::Long,
                    array_element: None,
                    param: None,
                    escaped: false,
                },
                OxLocal {
                    name: "b".to_string(),
                    ty: OxTy::Bool,
                    array_element: None,
                    param: None,
                    escaped: false,
                },
            ],
            temps: vec![OxTy::Bool],
            param_count: 0,
            return_local: None,
            blocks: vec![entry, then_blk, else_blk, fault, exit],
            entry: BlockId(0),
        };
        OxProgram {
            funcs: vec![main],
            entry: Some(FuncId(0)),
            unit_name: "VBAProject".to_string(),
            ..OxProgram::empty()
        }
    }

    fn bool_logical_program() -> OxProgram {
        let n = LocalId(0);
        let not_false = TempId(0);
        let cond = TempId(1);
        let entry = OxBlock {
            id: BlockId(0),
            instrs: vec![
                OxInst::Not {
                    dst: OxPlace::Temp(not_false),
                    src: OxOperand::Const(OxConst::Bool(false)),
                },
                OxInst::Logical {
                    dst: OxPlace::Temp(cond),
                    op: LogicalOp::And,
                    lhs: OxOperand::Const(OxConst::Bool(true)),
                    rhs: OxOperand::Use(OxPlace::Temp(not_false)),
                },
            ],
            fault_target: Some(BlockId(3)),
            terminator: OxTerminator::Branch {
                cond: OxOperand::Use(OxPlace::Temp(cond)),
                then_blk: BlockId(1),
                else_blk: BlockId(2),
            },
        };
        let then_blk = OxBlock {
            id: BlockId(1),
            instrs: vec![OxInst::Assign {
                dst: OxPlace::Local(n),
                value: OxOperand::Const(OxConst::I32(1)),
            }],
            fault_target: Some(BlockId(3)),
            terminator: OxTerminator::Return,
        };
        let else_blk = OxBlock {
            id: BlockId(2),
            instrs: vec![OxInst::Assign {
                dst: OxPlace::Local(n),
                value: OxOperand::Const(OxConst::I32(2)),
            }],
            fault_target: Some(BlockId(3)),
            terminator: OxTerminator::Return,
        };
        let fault = OxBlock {
            id: BlockId(3),
            instrs: Vec::new(),
            fault_target: None,
            terminator: OxTerminator::FaultDispatch {
                resume: BlockId(0),
                resume_next: BlockId(4),
            },
        };
        let exit = OxBlock {
            id: BlockId(4),
            instrs: Vec::new(),
            fault_target: None,
            terminator: OxTerminator::Return,
        };
        let main = OxFunc {
            name: "Main".to_string(),
            kind: ProcedureKind::Sub,
            locals: vec![local("n", OxTy::Long, None)],
            temps: vec![OxTy::Bool, OxTy::Bool],
            param_count: 0,
            return_local: None,
            blocks: vec![entry, then_blk, else_blk, fault, exit],
            entry: BlockId(0),
        };
        OxProgram {
            funcs: vec![main],
            entry: Some(FuncId(0)),
            unit_name: "VBAProject".to_string(),
            ..OxProgram::empty()
        }
    }

