    #[test]
    fn jit_call_helper_installs_missing_for_omitted_variant_arg() {
        unsafe extern "C" fn assert_missing_entry(
            run: *mut JitRun,
            _state: *mut RawExecState,
        ) -> i32 {
            if run.is_null() {
                return ST_FAULT;
            }
            // SAFETY: null was rejected and this test owns the synthetic run.
            let run = unsafe { &mut *run };
            let got_missing = run
                .frames
                .last()
                .and_then(|frame| frame.locals.first())
                .and_then(Variant::as_error_code)
                == Some(MISSING_ARG);
            if got_missing { ST_OK } else { ST_FAULT }
        }

        let entry = OxBlock {
            id: BlockId(0),
            instrs: Vec::new(),
            fault_target: None,
            terminator: OxTerminator::Return,
        };
        let callee = OxFunc {
            name: "Touch".to_string(),
            kind: ProcedureKind::Sub,
            locals: vec![OxLocal {
                name: "value".to_string(),
                ty: OxTy::Variant,
                array_element: None,
                param: Some(OxParamInfo {
                    by_ref: false,
                    variadic: false,
                }),
                escaped: false,
            }],
            temps: Vec::new(),
            param_count: 1,
            return_local: None,
            blocks: vec![entry],
            entry: BlockId(0),
        };
        let program = OxProgram {
            funcs: vec![callee],
            entry: None,
            unit_name: "VBAProject".to_string(),
            ..OxProgram::empty()
        };
        let mut globals = Vec::new();
        let functions: Vec<JitEntryFn> = vec![assert_missing_entry];
        let mut run = JitRun {
            globals: &mut globals,
            frames: vec![new_jit_frame(&program, &program.funcs[0]).expect("frame")],
            for_each: HashMap::new(),
            param_array_aliases: HashMap::new(),
            program: &program,
            functions: functions.as_ptr(),
            function_count: 1,
        };
        let host = NullHostServices::new(HostPolicy::default());
        let mut exec = ExecState::new(&host);
        exec.programs = vec![build_loaded(&program).expect("loaded")];
        let state = exec_state_as_raw(&mut exec);
        let args = [JitCallArgDesc {
            kind: JIT_CALL_ARG_OMITTED,
            aux: 0,
            value: 0,
            area: 0,
            index: 0,
        }];
        let status = unsafe { rt_jit_call_proc_i32(&mut run, state, 0, 1, args.as_ptr(), -1, -1) };
        assert_eq!(status, ST_OK);
    }

    #[test]
    fn jit_call_helper_copies_variant_return() {
        unsafe extern "C" fn set_variant_return(
            run: *mut JitRun,
            _state: *mut RawExecState,
        ) -> i32 {
            if run.is_null() {
                return ST_FAULT;
            }
            // SAFETY: null was rejected and this test owns the synthetic run.
            let run = unsafe { &mut *run };
            let Some(ret) = run
                .frames
                .last_mut()
                .and_then(|frame| frame.locals.first_mut())
            else {
                return ST_FAULT;
            };
            *ret = Variant::from_i32(77);
            ST_OK
        }

        let entry = OxBlock {
            id: BlockId(0),
            instrs: Vec::new(),
            fault_target: None,
            terminator: OxTerminator::Return,
        };
        let callee = OxFunc {
            name: "GetValue".to_string(),
            kind: ProcedureKind::Function,
            locals: vec![OxLocal {
                name: "GetValue".to_string(),
                ty: OxTy::Variant,
                array_element: None,
                param: None,
                escaped: false,
            }],
            temps: Vec::new(),
            param_count: 0,
            return_local: Some(LocalId(0)),
            blocks: vec![entry],
            entry: BlockId(0),
        };
        let program = OxProgram {
            funcs: vec![callee],
            globals: vec![OxGlobal {
                name: "g".to_string(),
                ty: OxTy::Variant,
                array_element: None,
            }],
            entry: None,
            unit_name: "VBAProject".to_string(),
            ..OxProgram::empty()
        };
        let mut globals = vec![Variant::empty()];
        let functions: Vec<JitEntryFn> = vec![set_variant_return];
        let mut run = JitRun {
            globals: &mut globals,
            frames: vec![new_jit_frame(&program, &program.funcs[0]).expect("frame")],
            for_each: HashMap::new(),
            param_array_aliases: HashMap::new(),
            program: &program,
            functions: functions.as_ptr(),
            function_count: 1,
        };
        let host = NullHostServices::new(HostPolicy::default());
        let mut exec = ExecState::new(&host);
        exec.programs = vec![build_loaded(&program).expect("loaded")];
        let state = exec_state_as_raw(&mut exec);
        let status = unsafe {
            rt_jit_call_proc_i32(
                &mut run,
                state,
                0,
                0,
                std::ptr::null(),
                AREA_GLOBAL as i32,
                0,
            )
        };
        assert_eq!(status, ST_OK);
        assert_eq!(globals.first().and_then(Variant::as_i32), Some(77));
    }

